    direct.push([]);
  }
  for(var i=1;i<input.length;i++){
    direct[input[i].split(' ')[0]-0].push(input[i].split(' ')[1]-0);
  }
  var memo=[];
  for(var i=1;i<=N;i++){
    memo.push([i]);
  }
  var temp;
  var str;
  while(memo.length>0){
    str='';
