    memo=temp.slice();
    memo.forEach(e=>{
      if(e[e.length-1]===e[0]){
        temp=e.slice();
        temp.shift();
        str=temp.length+"\n"+temp.join("\n");
      }
    });
    if(str!==''){
      console.log(str);
      return;
    }
  }
  console.log(-1);
